Here's a clean, idiomatic implementation in Java that merges overlapping intervals, along with comprehensive test cases to cover all edge cases.

---

### ✅ **Java Implementation**

```java
import java.util.*;

public class IntervalMerger {
    // Define the Interval class with generic type for numeric values
    public static class Interval<T extends Comparable<T>> {
        private final T start;
        private final T end;

        public Interval(T start, T end) {
            this.start = start;
            this.end = end;
        }

        public T getStart() {
            return start;
        }

        public T getEnd() {
            return end;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Interval)) return false;
            Interval<?> that = (Interval<?>) o;
            return start.equals(that.start) && end.equals(that.end);
        }

        @Override
        public int hashCode() {
            return Objects.hash(start, end);
        }

        @Override
        public String toString() {
            return "[" + start + ", " + end + "]";
        }
    }

    // Main function to merge intervals
    public static <T extends Comparable<T>> List<Interval<T>> mergeIntervals(List<Interval<T>> intervals) {
        if (intervals == null || intervals.isEmpty()) {
            return new ArrayList<>();
        }

        // Sort intervals by start value
        intervals.sort(Comparator.comparing(Interval::getStart));

        List<Interval<T>> merged = new ArrayList<>();
        merged.add(intervals.get(0));

        for (int i = 1; i < intervals.size(); i++) {
            Interval<T> current = intervals.get(i);
            Interval<T> last = merged.get(merged.size() - 1);

            // Check if current starts before or at the end of last
            if (current.getStart().compareTo(last.getEnd()) <= 0) {
                // Merge them
                T newStart = last.getStart();
                T newEnd = last.getEnd();
                if (current.getEnd().compareTo(newEnd) > 0) {
                    newEnd = current.getEnd();
                }
                merged.set(merged.size() - 1, new Interval<>(newStart, newEnd));
            } else {
                merged.add(current);
            }
        }

        return merged;
    }
}
```

